        B.append(int(data[2 + 2 * i]))
    adj = [0] * n
    for i in range(n):
        for j in range(n):
            if i != j and (A[i] == A[j] or B[i] == B[j]):
                adj[i] |= 1 << j
    sys.setrecursionlimit(10000)
    memo = {}

