        for _ in range(n)
    ]
    lines = [str(n)] + [f"{a} {b}" for a, b in cards]
    return "\n".join(lines) + "\n"

def validate(inp):
    t = inp.split()
    if len(t) < 1:
        return False
    try:
        n = int(t[0])
    except ValueError:
        return False
    if not (1 <= n <= 18):
        return False
    if len(t) != 1 + 2 * n:
        return False
    try:
        vals = [int(x) for x in t[1:]]
    except ValueError:
        return False
    return all(1 <= v <= 10**9 for v in vals)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    vals = [int(x) for x in t[1:]]
    A = [vals[2 * i] for i in range(n)]
    B = [vals[2 * i + 1] for i in range(n)]

    @lru_cache(maxsize=None)
    def win(mask):
        # True if the player to move (with remaining cards in mask) wins.
        for i in range(n):
            if not (mask >> i) & 1:
                continue
            for j in range(i + 1, n):
                if not (mask >> j) & 1:
                    continue
                if A[i] == A[j] or B[i] == B[j]:
                    nm = mask & ~(1 << i) & ~(1 << j)
                    if not win(nm):
                        return True
        return False

    return "Takahashi" if win((1 << n) - 1) else "Aoki"
